sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float angle;
uniform float frequency;
uniform float turbulence;
uniform float sharpness;
uniform float veinWidth;
uniform float speed;
layout(color) uniform half4 veinColor;
layout(color) uniform half4 baseColor;
uniform float blend;
uniform float amount;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(float2 p, float oct, float rough) {
    float v = 0.0;
    float a = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= oct) break;
        v += a * vnoise(p);
        norm += a;
        p = p * 2.03 + float2(11.7, 5.3);
        a *= rough;
    }
    return v / max(norm, 0.0001);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float a = radians(angle);
    float2 p = coord / max(scale, 1.0);
    float along = dot(p, float2(cos(a), sin(a)));
    float turb = fbm(p * 2.0 + time * speed, 5.0, 0.55);
    float v = abs(sin((along + turb * turbulence) * frequency));
    float vein = 1.0 - smoothstep(veinWidth * (1.0 - sharpness), veinWidth, v);
    float3 layer = mix(float3(baseColor.rgb), float3(veinColor.rgb), vein);
    float3 o = mix(s, blendm(s, layer, blend), amount);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), 1.0);
}
